  /**
   * A required option added with a null short name is still registered under a
   * null short key, so {@link Options#hasShortOption} reports it as present.
   */
  @Test(timeout = 4000)
  public void hasShortOption_returnsTrueForRequiredOptionWithNullShortName()  throws Throwable  {
      Options options = new Options();
      options.addRequiredOption((String) null, (String) null, true, "Y6.E))P%{qV#g");

      boolean hasNullShortOption = options.hasShortOption((String) null);

      assertTrue(hasNullShortOption);
  }

  /**
   * An empty Options set has no short options.
   */
  @Test(timeout = 4000)
  public void hasShortOption_returnsFalseWhenOptionWasNeverAdded()  throws Throwable  {
      Options options = new Options();

      boolean hasShortOption = options.hasShortOption("j");

      assertFalse(hasShortOption);
  }

  /**
   * An option added with a long name can be looked up by that long name.
   */
  @Test(timeout = 4000)
  public void hasOption_returnsTrueForRegisteredLongName()  throws Throwable  {
      Options options = new Options();
      options.addOption("v", " ]", false, "MBMwU(V1:l*[\"cE");

      boolean hasOption = options.hasOption(" ]");

      assertTrue(hasOption);
  }

  /**
   * A required option added with a long name can be looked up via
   * {@link Options#hasLongOption}.
   */
  @Test(timeout = 4000)
  public void hasLongOption_returnsTrueForRegisteredLongName()  throws Throwable  {
      Options options = new Options();
      options.addRequiredOption("j", "j", false, "g");

      boolean hasLongOption = options.hasLongOption("j");

      assertTrue(hasLongOption);
  }

  /**
   * An empty Options set has no long options.
   */
  @Test(timeout = 4000)
  public void hasLongOption_returnsFalseWhenOptionWasNeverAdded()  throws Throwable  {
      Options options = new Options();

      boolean hasLongOption = options.hasLongOption("T");

      assertFalse(hasLongOption);
  }

  /**
   * Looking up an unknown name returns null rather than throwing.
   */
  @Test(timeout = 4000)
  public void getOption_returnsNullForUnknownName()  throws Throwable  {
      Options options = new Options();

      Option option = options.getOption("v");

      assertNull(option);
  }

  /**
   * An empty partial name matches every registered long option, so the result
   * contains the single registered long name and is therefore not empty.
   */
  @Test(timeout = 4000)
  public void getMatchingOptions_emptyPrefixMatchesAllLongOptions()  throws Throwable  {
      Options options = new Options();
      options.addRequiredOption("j", "NR1W*T", false, "j");

      List<String> matchingOptions = options.getMatchingOptions("");

      assertFalse(matchingOptions.contains(""));
      assertFalse(matchingOptions.isEmpty());
  }

  /**
   * A prefix that matches no registered long option yields an empty list.
   */
  @Test(timeout = 4000)
  public void getMatchingOptions_returnsEmptyListWhenNoLongOptionMatches()  throws Throwable  {
      Options options = new Options();
      Options sameOptions = options.addRequiredOption("j", "j", false, "j");

      List<String> matchingOptions = sameOptions.getMatchingOptions(" ] [ long ");

      assertTrue(matchingOptions.isEmpty());
  }

  /**
   * An exact long name returns that single matching option.
   */
  @Test(timeout = 4000)
  public void getMatchingOptions_returnsExactLongNameMatch()  throws Throwable  {
      Options options = new Options();
      Options sameOptions = options.addRequiredOption("j", "j", false, "j");

      List<String> matchingOptions = sameOptions.getMatchingOptions("j");

      assertTrue(matchingOptions.contains("j"));
  }

  /**
   * Adding the contents of one Options into another that already holds an
   * option with the same key fails with a "Duplicate key" exception.
   */
  @Test(timeout = 4000)
  public void addOptions_throwsOnDuplicateKey()  throws Throwable  {
      Options options = new Options();
      Options optionsWithNullKey = options.addOption((String) null, (String) null);

      // options already contains the null-key option, so merging it again
      // is a duplicate.
      try {
        options.addOptions(optionsWithNullKey);
        fail("Expecting exception: IllegalArgumentException");

      } catch(IllegalArgumentException e) {
         //
         // Duplicate key: null
         //
         verifyException("org.apache.commons.cli.Options", e);
      }
  }

  /**
   * Merging the options of a distinct Options instance returns the receiver,
   * which is a different instance from the source.
   */
  @Test(timeout = 4000)
  public void addOptions_returnsReceiverNotSource()  throws Throwable  {
      Options target = new Options();
      Options source = new Options();
      source.addOption("v", " ]", false, "MBMwU(V1:l*[\"cE");

      Options result = target.addOptions(source);

      assertNotSame(source, result);
  }

  /**
   * {@link Options#addOptionGroup} returns the same Options instance when the
   * group is required.
   */
  @Test(timeout = 4000)
  public void addOptionGroup_returnsSameInstanceForRequiredGroup()  throws Throwable  {
      Options options = new Options();
      OptionGroup requiredGroup = new OptionGroup();
      requiredGroup.setRequired(true);

      Options result = options.addOptionGroup(requiredGroup);

      assertSame(options, result);
  }

  /**
   * {@link Options#addOptionGroup} returns the same Options instance when the
   * group is optional.
   */
  @Test(timeout = 4000)
  public void addOptionGroup_returnsSameInstanceForOptionalGroup()  throws Throwable  {
      Options options = new Options();
      OptionGroup optionalGroup = new OptionGroup();

      Options result = options.addOptionGroup(optionalGroup);

      assertSame(result, options);
  }

  /**
   * An Option fetched from one Options instance keeps its required flag and
   * no-argument setting when added to another Options instance.
   */
  @Test(timeout = 4000)
  public void addOption_preservesRequiredAndNoArgFlags()  throws Throwable  {
      Options options = new Options();
      Options sameOptions = options.addRequiredOption("j", "j", false, "j");
      Option requiredOption = sameOptions.getOption("j");

      options.addOption(requiredOption);

      assertTrue(requiredOption.isRequired());
      assertFalse(requiredOption.hasArg());
  }

  /**
