  @Test(timeout = 4000)
  public void toString_describesEmptyOptions()  throws Throwable  {
      Options options = new Options();

      String description = options.toString();

      assertEquals("[ Options: [ short {} ] [ long {} ]", description);
  }

  /**
   * A freshly created Options set has no required options.
   */
  @Test(timeout = 4000)
  public void getRequiredOptions_isEmptyForNewOptions()  throws Throwable  {
      Options options = new Options();

      List<?> requiredOptions = options.getRequiredOptions();

      assertTrue(requiredOptions.isEmpty());
  }

  /**
   * The short-name + description overload of addOption returns the same
   * Options instance for fluent chaining.
   */
  @Test(timeout = 4000)
  public void addOption_returnsSameInstanceForShortNameAndDescription()  throws Throwable  {
      Options options = new Options();

      Options result = options.addOption((String) null, false, "NO_ARGS_ALLOWED");

      assertSame(options, result);
  }
